write('/peer/', layout({ route: '/peer/', title: 'Operations and Supply Chain Thinking | Peer | Phull Insights', description: 'Explore practical perspectives, case studies and frameworks across operations, supply chain, MedTech, transformation and sustainable performance.', eyebrow: 'Peer journey', h1: 'Practical thinking for people who run and change operations.', lead: 'Explore operating questions, case studies, frameworks and perspectives grounded in practical experience.', breadcrumbs: [{ name: 'Home', path: '/' }, { name: 'Peer', path: '/peer/' }], body: `<section class="content-section layers-section section-border"><div class="container editorial-split"><div><p class="eyebrow">Layers of understanding</p><h2>Understanding opens in layers.</h2><p>Phull (ਫੁੱਲ) means flower in Punjabi. Here, that meaning is used as a brand metaphor for understanding opening in layers. No additional language or historical derivation is claimed.</p></div><div class="layers-visual" role="img" aria-label="Layers of Understanding visual showing insight opening in successive layers"><i></i><i></i><i></i><i></i></div></div></section><section class="content-section section-border"><div class="container"><div class="topic-grid"><a href="/insights/"><span>01</span><strong>Operations</strong><em>Explore →</em></a><a href="/insights/"><span>02</span><strong>Supply Chain</strong><em>Explore →</em></a><a href="/insights/cold-chain-sla-redesign/"><span>03</span><strong>MedTech</strong><em>Explore →</em></a><a href="/methodology/"><span>04</span><strong>Transformation</strong><em>Explore →</em></a><a href="/insights/inventory-service-protected/"><span>05</span><strong>Sustainable Performance</strong><em>Explore →</em></a></div></div></section><section class="latest-section section-border"><div class="container"><div class="section-heading compact-heading"><div><p class="eyebrow">Featured thinking</p><h2>Questions worth exploring.</h2></div><a class="text-link" href="/insights/">All insights →</a></div><div class="editorial-grid"><a class="editorial-card visual-otif" href="/insights/otif-score-that-hid-the-real-problem/"><span class="editorial-visual" aria-hidden="true"><i></i><i></i><i></i></span><span class="card-tag">Case study</span><strong>The OTIF score that hid the real problem</strong><small>Supply chain</small><em>Read →</em></a><a class="editorial-card visual-rhythm" href="/methodology/"><span class="editorial-visual" aria-hidden="true"><i></i><i></i><i></i></span><span class="card-tag">Practical framework</span><strong>Map. Measure. Diagnose. Rebuild.</strong><small>Transformation</small><em>Explore →</em></a><a class="editorial-card visual-sustainable" href="/insights/inventory-service-protected/"><span class="editorial-visual" aria-hidden="true"><i></i><i></i><i></i></span><span class="card-tag">Perspective</span><strong>How can inventory fall without collapsing service?</strong><small>Sustainable performance</small><em>Read →</em></a></div></div></section><section class="contact-strip section-border"><div class="container contact-strip-inner"><div><p class="eyebrow">Continue the discussion</p><h2>Bring a method, operating question or perspective worth challenging.</h2></div><a class="btn btn-primary" data-event="peer_contact" href="mailto:hello@phullinsights.com?subject=Peer%20or%20speaking%20enquiry">Start a conversation</a></div></section>` }));

write('/executive-leadership/', layout({ route: '/executive-leadership/', title: 'Executive Operations Leadership Profile | Phull Insights', description: 'Executive operations, supply chain and transformation leadership profile for Director, COO and VP-level mandates.', eyebrow: 'Recruiter route · Executive leadership', h1: 'Executive operations leadership for complex, multi-site environments.', lead: 'A recruiter-focused profile of level, functional breadth, sectors and scale—kept separate from consultancy sales content.', breadcrumbs: [{ name: 'Home', path: '/' }, { name: 'Executive leadership', path: '/executive-leadership/' }], schemas: [person], body: `<section class="content-section section-border"><div class="container"><div class="profile-grid"><article><p class="card-tag">Target level</p><h2>Director, COO and VP-level mandates</h2><p>Roles where operational judgement, transformation discipline and cross-functional accountability need to work together.</p></article><article><p class="card-tag">Functional breadth</p><h2>Operations · Supply chain · Transformation</h2><p>Operating-model leadership, multi-site performance, programme recovery and technology-enabled change.</p></article><article><p class="card-tag">Sectors</p><h2>Regulated MedTech · Distribution · Complex operations</h2><p>Environments where service, cost, risk and governance cannot be assessed in isolation.</p></article><article><p class="card-tag">Scale</p><h2>Responsibilities shown separately</h2><p>£230m revenue scope and £100m P&amp;L accountability. The figures are not combined.</p></article></div></div></section><section class="content-section section-border"><div class="container split-layout"><div class="rich-copy"><p class="eyebrow">Leadership pattern</p><h2>Strategy that survives contact with delivery.</h2><ul><li>Translate executive intent into an operating rhythm and accountable decisions.</li><li>Distinguish structural problems from imported performance.</li><li>Connect programme governance to service, cost, people and risk.</li><li>Build evidence that boards and operating teams can challenge.</li><li>Hand over routines that do not depend on one individual.</li></ul><p><a class="text-link" href="https://uk.linkedin.com/in/pupsi" rel="me external">Read third-party recommendations on LinkedIn →</a></p></div><aside class="side-panel"><h3>Recruiter next step</h3><p>Share the mandate, level, sector and success profile. No CV link is planned at present.</p><a class="btn btn-primary" data-event="recruiter_contact" href="mailto:hello@phullinsights.com?subject=Executive%20mandate%20discussion">Discuss an executive mandate</a></aside></div></section>` }));
write('/executive-leadership/', redirectPage('/recruiter/'));

