write('/insights/', layout({ route: '/insights/', title: 'Operations Case Studies and Insights | Phull Insights', description: 'Anonymised operations and supply chain cases covering OTIF, inventory, cold chain, MedTech, networks and improvement.', eyebrow: 'Peer route · Insights hub', h1: 'Operating questions, methods and evidence boundaries.', lead: 'Ten priority cases are approved for anonymised use. The first three have complete case pages; seven are queued for drafting without company names or unverified metrics.', breadcrumbs: [{ name: 'Home', path: '/' }, { name: 'Insights', path: '/insights/' }], body: `<section class="content-section section-border"><div class="container"><div class="insight-grid">${insightTopics.map((topic, index) => `<article class="insight-card"><div class="insight-meta"><span>${String(index + 1).padStart(2, '0')}</span><span>${topic.state === 'published' ? 'Anonymised case' : 'Anonymised case queued'}</span></div><h2>${topic.title}</h2><p>${topic.summary}</p>${topic.state === 'published' ? `<a class="text-link" href="/insights/${topic.slug}/">Read case <span aria-hidden="true">→</span></a>` : '<p class="held-note">Company names are excluded. The page and any metrics await source review.</p>'}</article>`).join('')}</div></div></section><section class="content-section section-border"><div class="container split-layout"><div><p class="eyebrow">Editorial rule</p><h2>Anonymise identity. Verify every number.</h2><p class="lead-copy">Owner approval permits case narratives without company names. Metrics remain unpublished until the source, period, baseline and wording have a recorded evidence decision.</p></div><aside class="side-panel"><h3>Every published case includes</h3><ul><li>Challenge and context</li><li>Diagnosis and rebuild</li><li>Evidence decision</li><li>Questions for the reader</li><li>Related service and case links</li><li>Author and preview date</li></ul></aside></div></section>` }));

const casePages = {
  'otif-score-that-hid-the-real-problem': { title: 'The OTIF Score That Hid the Real Problem | Phull Insights', h1: 'The OTIF score that hid the real problem', description: 'A method-only case for diagnosing OTIF boundaries, promise logic, exceptions and customer delivery confirmation.', sector: 'Distribution and multi-site operations', challenge: 'A headline OTIF score can remain stable while customer promises change repeatedly, orders require manual intervention and the internal measure stops before confirmed delivery.', diagnosis: 'Reconstruct requirement, commitment, promise change, shipment, delivery confirmation and exception handling as one event sequence. Then test which date and event the organisation uses as success.', rebuild: 'Agree a service definition, preserve the original and changed promises, show exceptions before failure and assign ownership for each decision point.', questions: ['Does the measure stop at despatch or confirmed delivery?', 'How many promise changes occur before a line scores on time?', 'Which exceptions were imported and which were created internally?', 'What management effort is invisible in the score?'], service: ['/services/supply-chain-consultancy/', 'Supply Chain Consultancy'], related: ['/insights/inventory-service-protected/', 'Inventory with service protected'] },
  'inventory-service-protected': { title: 'Inventory Reduction With Service Protected | Phull Insights', h1: 'How can inventory fall without collapsing service?', description: 'A method-only case for segmenting inventory, service, constraints and availability before changing stock policy.', sector: 'Supply chain and inventory management', challenge: 'Aggregate stock can rise while customer availability deteriorates. A broad reduction target can remove the wrong inventory and increase expediting.', diagnosis: 'Segment demand, lead time, lifecycle, constraint, customer promise and stock state. Distinguish physical stock from operationally available stock and trace where uncertainty enters.', rebuild: 'Change policy by segment, test the service effect, make exceptions visible and verify the result at 30 and 90 days before scaling.', questions: ['Which inventory is unavailable despite being physically present?', 'Where is buffer compensating for unreliable lead time or data?', 'Which service definition must be protected?', 'What evidence would stop the reduction?'], service: ['/services/supply-chain-consultancy/', 'Supply Chain Consultancy'], related: ['/insights/otif-score-that-hid-the-real-problem/', 'Delivery-confirmed OTIF'] },
  'cold-chain-sla-redesign': { title: 'Cold-Chain SLA Redesign: A Method-Only Case | Phull Insights', h1: 'Why can a green SLA still produce quarantined stock?', description: 'A method-only case for aligning cold-chain service measures, product thresholds, dwell time and human review.', sector: 'Temperature-controlled and regulated logistics', challenge: 'A consignment can meet a contracted time-and-temperature measure while still failing the product-specific operating threshold used by the receiving organisation.', diagnosis: 'Map contracted milestones, product thresholds, packaging configuration, hub dwell, release dependencies and the customer decision that determines usable stock.', rebuild: 'Align the measurement boundary to the product journey, set accountable dwell thresholds and retain qualified human judgement for disposition and regulatory decisions.', questions: ['Which threshold determines customer usability?', 'Where does dwell accumulate?', 'Do the contract and product profiles use the same event boundary?', 'Who is accountable for reviewing an excursion?'], service: ['/services/medtech-supply-chain/', 'MedTech Supply Chain'], related: ['/insights/otif-score-that-hid-the-real-problem/', 'Delivery-confirmed OTIF'] },
};

for (const [slug, entry] of Object.entries(casePages)) {
  const route = `/insights/${slug}/`;
  const article = { '@context': 'https://schema.org', '@type': 'Article', headline: entry.h1, description: entry.description, datePublished: '2026-09-20', dateModified: '2026-09-20', author: { '@type': 'Person', name: 'Pupsi Phull' }, publisher: { '@type': 'Organization', name: 'Phull Insights' }, mainEntityOfPage: `${productionBase}${route}` };
  write(route, layout({ route, title: entry.title, description: entry.description, eyebrow: `Anonymised case · ${entry.sector}`, h1: entry.h1, lead: entry.description, pageType: 'article', breadcrumbs: [{ name: 'Home', path: '/' }, { name: 'Insights', path: '/insights/' }, { name: entry.h1, path: route }], schemas: [article], body: `<article class="content-section section-border"><div class="container article-layout"><div class="article-meta"><span>Anonymised case</span><span>Author: Pupsi Phull</span><span>${buildLabel}</span></div><div class="review-note"><strong>Evidence decision:</strong> owner approval permits anonymised case use. Company names are excluded; metrics remain omitted until source, period and baseline are verified.</div><div class="rich-copy"><h2>Challenge</h2><p>${entry.challenge}</p><h2>Diagnosis</h2><p>${entry.diagnosis}</p><h2>Rebuild</h2><p>${entry.rebuild}</p><h2>Questions for the reader</h2><ul>${entry.questions.map((question) => `<li>${question}</li>`).join('')}</ul></div><div class="related-panel"><a href="${entry.service[0]}">${entry.service[1]} <span aria-hidden="true">→</span></a><a href="${entry.related[0]}">Related case: ${entry.related[1]} <span aria-hidden="true">→</span></a><a href="/insights/">All Insights <span aria-hidden="true">→</span></a><a href="/contact/">Discuss the operating question <span aria-hidden="true">→</span></a></div></div></article>` }));
}

write('/trust/', layout({ route: '/trust/', title: 'Working With Phull Insights | Trust, Data and Human Review', description: 'How Phull Insights approaches scoping, confidentiality, data minimisation, human review, AI use, retention and subcontractors.', eyebrow: 'Trust and working principles', h1: 'A useful diagnosis must be proportionate, explainable and safe to challenge.', lead: 'This preview describes the intended operating principles. Contractual controls and provider details remain unpublished until documentary evidence and legal review are complete.', breadcrumbs: [{ name: 'Home', path: '/' }, { name: 'Trust', path: '/trust/' }], body: `<section class="content-section section-border"><div class="container"><div class="step-grid trust-steps"><article><span>01</span><h2>Scope</h2><p>Agree the decision question, roles, exclusions and minimum evidence boundary.</p></article><article><span>02</span><h2>Control</h2><p>Confirm permitted data, access, providers, transfer method, retention and deletion before data moves.</p></article><article><span>03</span><h2>Review</h2><p>Keep calculations, caveats, assumptions and alternative explanations visible to accountable people.</p></article><article><span>04</span><h2>Close</h2><p>Agree handover, deletion evidence, unresolved risks and the owner of each next action.</p></article></div></div></section><section class="content-section section-border"><div class="container split-layout"><div class="rich-copy"><h2>Minimum necessary data</h2><p>Only operational evidence needed to answer the agreed question should be requested. Patient data, special-category personal data and confidential files are not required for the initial conversation and should not be sent.</p><h2>Human review and AI use</h2><p>Deterministic metrics and financial logic should remain documented and reconcilable. AI may assist with approved unstructured material or narrative drafting, but accountable human review remains part of every finding and recommendation.</p><h2>Client systems and subcontractors</h2><p>System access, processors, specialist support and subcontractors must be engagement-specific, approved and documented. This preview does not imply that any particular provider or control is already in place.</p><h2>Retention and deletion</h2><p>Use a documented, purpose-based schedule; review records regularly; delete or anonymise them when the purpose ends. Proposed web-enquiry periods are listed on the privacy page for owner and legal review.</p></div><aside class="side-panel"><h3>Current disclosure position</h3><ul><li>No insurance claim is published</li><li>No accreditation or formal certification is claimed</li><li>Standard contractual protections await approval</li><li>Subprocessors and data locations await provider selection</li><li>Third-party recommendations are referenced only through LinkedIn</li></ul></aside></div></section>` }));

write('/privacy/', layout({ route: '/privacy/', title: 'Privacy Outline | Phull Insights', description: 'Preview privacy outline for Phull Insights business enquiries, with confirmed controller wording and approved retention periods.', eyebrow: 'Privacy · Preview outline', h1: 'A narrow privacy foundation for business enquiries.', lead: 'This is a non-production outline. The controller wording and retention periods are owner-approved; the postal address, providers, data flows and approval date still require completion before publication.', breadcrumbs: [{ name: 'Home', path: '/' }, { name: 'Privacy outline', path: '/privacy/' }], body: `<section class="content-section section-border"><div class="container narrow rich-copy"><div class="review-note"><strong>Data controller:</strong> Pupsi Phull trading as Full Insight.<br><strong>Postal address:</strong> To be updated before production. No company, registered-office or jurisdiction statement is claimed.</div><h2>Information in scope</h2><p>A business enquiry may include a name, work contact details, organisation, role, selected route and the information supplied about an operational or executive mandate.</p><h2>Proposed purposes and lawful basis</h2><p>The intended purposes are to respond to an enquiry, assess fit, take steps requested before a contract and manage a legitimate business relationship. The final lawful-basis wording requires legal review against the actual form, analytics and providers.</p><h2>Data minimisation</h2><p>Do not send patient data, special-category personal data, confidential operational files or credentials through the initial enquiry route.</p><h2>Approved retention schedule</h2><ul><li>Client, recruiter and peer enquiries that do not progress: delete or anonymise 12 months after the last meaningful contact.</li><li>Analytics events, if enabled with valid consent: retain for no more than 14 months, then aggregate or delete.</li><li>Consent records: retain only as long as needed to demonstrate the active choice and handle withdrawal.</li><li>Contracts, invoices and engagement records: set a separate legally reviewed period based on actual tax, contractual and limitation requirements.</li></ul><p>These are approved working periods, not a claimed universal standard. Review them regularly and delete earlier when the purpose has ended.</p><h2>Cookies and analytics</h2><p>The preview uses local storage only to remember the colour-theme choice and does not run analytics. The production analytics platform remains open. If analytics is enabled, non-essential tracking must remain off until consent; Accept all, Reject all and Manage choices must be equally available; withdrawal must be possible; and Client, Recruiter and Peer route events must be recorded separately only after consent.</p><h2>Providers and transfers</h2><p>The hosted-form and spam-protection providers remain open. Hosting, email, form, analytics, data-location and international-transfer details will be inserted only after the selected services and settings are confirmed.</p><h2>Rights and complaints</h2><p>The production notice will explain access, correction, deletion, restriction, objection and complaint routes, including the UK Information Commissioner where applicable.</p><h2>Privacy contact</h2><p>Until the final notice is approved, privacy questions may be sent to <a href="mailto:hello@phullinsights.com?subject=Privacy%20question">hello@phullinsights.com</a>.</p></div></section>` }));

write('/journeyiq/', layout({ route: '/journeyiq/', title: 'JourneyIQ Operational Diagnostic Concept | Phull Insights', description: 'JourneyIQ is a bounded operational diagnostic concept that structures signals into a reviewable decision brief.', eyebrow: 'JourneyIQ · Diagnostic concept', h1: 'Turn fragmented signals into a clearer decision.', lead: 'A service-led diagnostic within Phull Insights, designed to structure operational evidence before a broader intervention is chosen.', breadcrumbs: [{ name: 'Home', path: '/' }, { name: 'JourneyIQ', path: '/journeyiq/' }], body: `<section class="content-section section-border"><div class="container journey-hero-grid"><div><p class="eyebrow">Simple by design</p><h2>Signals → JourneyIQ → Decision</h2><p>Start with the management question and the minimum approved evidence set. Structure the signals, expose material issues and support accountable human judgement.</p><div class="review-note"><strong>Illustrative scenario.</strong> Not a live client implementation or verified customer outcome.</div></div><div class="journey-simple" role="img" aria-label="JourneyIQ illustration showing operational signals converging through JourneyIQ into a structured decision"><span>Signals</span><i>JourneyIQ</i><strong>Decision</strong></div></div></section><section class="journey-detail section-border"><div class="container"><p class="eyebrow">JourneyIQ · Signal review</p><h2>Turn unstructured signals into operational intelligence.</h2><div class="signal-decision" role="img" aria-label="JourneyIQ illustration showing multiple supply chain signals converging into a structured decision brief"><div><span>Batch delayed</span><span>Conflicting ETA</span><span>Safety stock</span><span>Quality release</span><span>Freight partner</span></div><i>JourneyIQ</i><strong>Decision brief<small>Material issues · Recommended actions · Reviewable</small></strong></div><p class="visual-disclaimer">Illustrative scenario. Not a live client implementation or verified customer outcome.</p></div></section><section class="journey-risk section-border"><div class="container editorial-split"><div><p class="eyebrow">JourneyIQ · Signal review</p><h2>Separate urgent risk from background noise.</h2><p>The purpose is not to make an automated decision. It is to make the evidence, dependencies and uncertainty easier for an accountable leader to review.</p></div><div class="risk-line" role="img" aria-label="Illustrative supply chain timeline highlighting an urgent delayed batch among background operational signals"><span>Supplier</span><i>Delayed batch</i><span>Consolidation hub</span><span>Allocation</span></div></div><p class="container visual-disclaimer">Illustrative scenario. Not a live client implementation or verified customer outcome.</p></section><section class="content-section section-border"><div class="container editorial-split"><div><p class="eyebrow">Boundaries</p><h2>Evidence support, not automated authority.</h2><p>JourneyIQ does not imply current customers, completed implementations, verified savings, clinical use, regulatory approval or production security certification.</p></div><aside class="editorial-aside"><h3>Before any live pilot</h3><p>Commercial scope, allowed datasets, access, retention, review ownership and success criteria would need to be agreed.</p><a class="text-link" href="/trust/">Review trust principles →</a></aside></div></section>${primaryCta('Start with the management question. Then decide what evidence is worth assembling.')}` }));

write('/contact/', layout({ route: '/contact/', title: 'Contact Phull Insights | Operations Advisory Enquiries', description: 'Choose a client, recruiter or peer enquiry route for Phull Insights. No operational data is needed for the first conversation.', eyebrow: 'Contact · Route-specific enquiries', h1: 'Start with the reason for the conversation.', lead: 'Choose the route that fits. All three routes are designed to reach Pupsi at hello@phullinsights.com and to be tracked separately. The preview form remains disabled until the hosted provider and spam controls are approved.', breadcrumbs: [{ name: 'Home', path: '/' }, { name: 'Contact', path: '/contact/' }], body: `<section class="content-section section-border"><div class="container contact-layout"><div class="contact-route-list"><article data-route="client"><p class="card-tag">Client</p><h2>Request a 30-minute Operational Diagnostic</h2><p>Share the operating symptom and the decision that is difficult to make. No operational files are needed.</p></article><article data-route="recruiter"><p class="card-tag">Recruiter</p><h2>Discuss an executive mandate</h2><p>Share the level, scope, sector and success profile for a confidential fit conversation.</p></article><article data-route="peer"><p class="card-tag">Peer</p><h2>Exchange methods or commentary</h2><p>Share a method, speaking topic or operating question worth exploring.</p></article></div><div class="form-panel"><form id="preview-contact-form" action="/contact/thank-you/" method="post"><fieldset><legend>Rich hosted-form specification</legend><label for="route">Enquiry route</label><select id="route" name="route" required><option value="client">Client</option><option value="recruiter">Recruiter</option><option value="peer">Peer or speaking</option></select><label for="name">Name</label><input id="name" name="name" autocomplete="name" required><label for="email">Work email</label><input id="email" name="email" type="email" autocomplete="email" required><label for="organisation">Organisation</label><input id="organisation" name="organisation" autocomplete="organization"><label for="role">Role or mandate</label><input id="role" name="role" autocomplete="organization-title"><label for="message">What decision or mandate do you want to discuss?</label><textarea id="message" name="message" rows="5" required></textarea><label class="consent-check"><input type="checkbox" name="privacy_acknowledgement" required> I understand this information will be used to respond to my enquiry.</label><p class="form-warning">Do not send patient data, special-category personal data, confidential files or operational extracts.</p><button class="btn btn-primary" type="submit">Preview form only</button><p class="form-status" id="form-status" role="status"></p></fieldset></form><p>Planned recipient for every route: <a data-event="email_click" href="mailto:hello@phullinsights.com">hello@phullinsights.com</a>. No response-time promise is made.</p></div></div></section>` }));

write('/contact/thank-you/', layout({ route: '/contact/thank-you/', title: 'Enquiry Received | Phull Insights', description: 'Preview acknowledgement page for a Phull Insights enquiry.', eyebrow: 'Preview acknowledgement', h1: 'Thank you.', lead: 'This route is ready for a future hosted form, but no submission reaches it in this preview.', breadcrumbs: [{ name: 'Home', path: '/' }, { name: 'Contact', path: '/contact/' }, { name: 'Thank you', path: '/contact/thank-you/' }], body: `<section class="content-section section-border"><div class="container narrow"><p>Your enquiry has been recorded. This acknowledgement deliberately makes no response-time promise.</p><p>The production form remains blocked until a hosted-form provider, privacy wording, spam protection and end-to-end delivery to hello@phullinsights.com are approved and tested.</p><a class="text-link" href="/contact/">Return to contact</a></div></section>` }));

const routes = ['/', '/client/', '/recruiter/', '/peer/', '/services/', ...services.map((service) => `/services/${service.slug}/`), '/methodology/', '/about/', '/insights/', ...Object.keys(casePages).map((slug) => `/insights/${slug}/`), '/trust/', '/privacy/', '/journeyiq/', '/contact/', '/contact/thank-you/'];

fs.copyFileSync(path.resolve(__dirname, 'preview.css'), path.join(out, 'styles.css'));
fs.copyFileSync(path.resolve(__dirname, 'preview.js'), path.join(out, 'app.js'));
fs.cpSync(path.resolve(__dirname, 'assets/social'), path.join(out, 'social'), { recursive: true });
fs.writeFileSync(path.join(out, 'favicon.svg'), `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 64 64"><rect width="64" height="64" rx="14" fill="#1b3a4b"/><path d="M18 18v28M18 32h18c7 0 11-3 11-8s-4-8-11-8H18M35 32l13 14" fill="none" stroke="#d4943c" stroke-width="5" stroke-linecap="round" stroke-linejoin="round"/></svg>`);
fs.writeFileSync(path.join(out, 'robots.txt'), 'User-agent: *\nDisallow: /\n');
